('columbia-accident', '3.7 DEBRIS ANALYSIS', 'eakup-video-700', '77', 'eakup (video) — 700 sumed forward — 9'),
('columbia-accident', '3.7 DEBRIS ANALYSIS', 'lage-separation', '77', 'lage separation'),
('columbia-accident', '3.7 DEBRIS ANALYSIS', '00-20-6-650', '77', ':00:20.6 — 650'),
('columbia-accident', '3.7 DEBRIS ANALYSIS', '600-breach-00-50', '77', '600 in Breach :00:50'),
('columbia-accident', '3.7 DEBRIS ANALYSIS', 'sat-predicted-7', '77', 'SAT predicted) — 7 148,800 ft 7.7 g''s — 550'),
