('columbia-accident', '6.2 SCHEDULE PRESSURE', 'columbia-caught-middle', '137', 'Columbia: Caught in the Middle'),
('columbia-accident', '6.2 SCHEDULE PRESSURE', 'launch-launch-launch-launch-cutout', '137', 'Launch Launch Launch Launch Cutout Cutout Cutout Cutout'),
