INSERT INTO passages (report, section, paragraph_id, page, body) VALUES
('us-deepwater-horizon', 'Front matter', 'i-i', NULL, 'i i'),
('us-deepwater-horizon', 'Front matter', 'dedication-report-dedicated-11-men', NULL, 'Dedication This report is dedicated to the 11 men who lost their lives on the Deepwater Horizon rig on April 20, 2010 and to their families, in hope that this report will help minimize the chance of another such disaster ever happening again. Jason Anderson Aaron Dale Burkeen Donald Clark Stephen Curtis Gordon Jones Roy Wyatt Kemp Karl Dale Kleppinger, Jr. Blair Manuel Dewey Revette Shane Roshto Adam Weise ii'),
('us-deepwater-horizon', 'Front matter', 'cover-photo-steadfast-tv', NULL, 'Cover Photo: © Steadfast TV'),
('us-deepwater-horizon', 'Front matter', 'isbn-978-0-16-087371-3-iii-iii', NULL, 'ISBN: 978-0-16-087371-3 iii iii'),
('us-deepwater-horizon', 'Front matter', 'deep-water-gulf-oil-disaster', NULL, 'Deep Water The Gulf Oil Disaster and the Future of Offshore Drilling Report to the President National Commission on the BP Deepwater Horizon Oil Spill and Offshore Drilling January 2011 iv'),
