('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'combined-lost-circulation-yes-saved', '125', 'Combined Lost Circulation Yes Saved Time BP on Shore'),
('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'materials-avoid-disposal-issues', '125', 'Materials to Avoid Disposal Issues'),
('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'displacing-mud-from-riser-before', '125', 'Displacing Mud from Riser Before'),
('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'yes-unclear-bp-shore', '125', 'Yes Unclear BP on Shore'),
('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'setting-surface-cement-plug', '125', 'Setting Surface Cement Plug'),
('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'setting-surface-cement-plug-3', '125', 'Setting Surface Cement Plug 3,000 BP on Shore'),
('us-deepwater-horizon', 'DEVELOPMENT & PRODUCTION PLAN DEVELOPMENT & PRODUCTION PLAN APPROVED PRODUCTION WELL APPLICATION FIRST OIL / GAS PRODUCTION', 'yes-unclear', '125', 'Yes Unclear'),
